from itertools import combinations
import random

def find_clique_size(edges, n):
    """Find the maximum clique size in a graph."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    max_clique = 1

    def bron_kerbosch(r, p, x):
        nonlocal max_clique
        if not p and not x:
            max_clique = max(max_clique, len(r))
            return
        for v in list(p):
            bron_kerbosch(r | {v}, p & adj[v], x & adj[v])
            p.remove(v)
            x.add(v)

    bron_kerbosch(set(), set(range(n)), set())
    return max_clique

def can_color_with_k(edges, n, k):
    """Check if graph can be colored with k colors."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * n

    def is_safe(v, c):
        for neighbor in adj[v]:
            if colors[neighbor] == c:
                return False
        return True

    def solve(v):
        if v == n:
            return True
        for c in range(k):
            if is_safe(v, c):
                colors[v] = c
                if solve(v + 1):
                    return True
                colors[v] = -1
        return False

    return solve(0)

