from itertools import combinations

def find_cliques(edges, n, size):
    """Find all cliques of a given size."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    cliques = []
    for combo in combinations(range(n), size):
        is_clique = True
        for i in range(size):
            for j in range(i+1, size):
                if combo[j] not in adj[combo[i]]:
                    is_clique = False
                    break
            if not is_clique:
                break
        if is_clique:
            cliques.append(combo)
    return cliques

